def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyz'

    def word():
        w = ''.join(rng.choice(letters) for _ in range(rng.randint(1, 6)))
        r = rng.random()
        if r < 0.2:
            w = w.upper()
        elif r < 0.4:
            w = w.capitalize()
        return w

    def sentence(maxw):
        k = rng.randint(1, maxw)
        s = ' ' * rng.randint(0, 2)
        for i in range(k):
            if i:
                s += ' ' * rng.randint(1, 3)
            s += word()
        return s + ' ' * rng.randint(0, 1) + '.'

    def big(maxw, target):
        parts, total = [], 0
        while True:
            s = sentence(maxw)
            if total + len(s) > target:
                break
            parts.append(s)
            total += len(s)
        return ''.join(parts)

    tests = ['a.', 'One two three four five.', 'one two three four.', 'Hello   World  .  ',
             'A b c d.E f g h i.', 'THE   END   IS   NEAR   NOW  .   ', 'x y z w v u.', 'ab.cd.ef.']
    for _ in range(30):
        while True:
            t = ''.join(sentence(8) for _ in range(rng.randint(1, 4))) + ' ' * rng.randint(0, 2)
            if len(t) < 380:
                break
        tests.append(t)
    tests.append(big(4, 100000))
    tests.append(big(10, 100000))
    tests.append(big(1, 100000))
    tests.append(big(5, 100000))
    return tests
